// 1. Gemini se raw text string nikaalo
let rawText = $input.first().json.content.parts[0].text;

// 2. Agar Gemini ne galti se ```json aur ``` laga diya hai, toh usko hatao (clean karo)
let cleanText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();

// 3. Uss text ko ek ASLI JSON object me convert karo
let finalData = JSON.parse(cleanText);

// 4. Data ko aage bhejo
return finalData;
